INCIDENTS: list[dict] = []
NEGATIVES: list[dict] = []
SUCCESS_CRITERIA: list[dict] = []


def inc(turn: int, cat: str, quote: str, **kw) -> None:
    """Добавить вхождение дефекта (по умолчанию origin="model", conf="plausible")."""
    row = {"turn": turn, "cat": cat, "quote": quote, "origin": "model", "det": "run",
           "det_turn": None, "uq": "", "rule_turn": None, "rule_uq": "", "sec": "3",
           "conf": "plausible", "note": ""}
    row.update(kw)
    if row["det_turn"] is not None and row["det_turn"] < row["turn"]:
        # Цитата БА сказана до дефекта: это нарушенное правило, а не обнаружение.
        row["rule_turn"], row["rule_uq"] = row["det_turn"], row["uq"]
        row["det_turn"], row["uq"] = None, ""
    INCIDENTS.append(row)


def neg(turn: int, set_code: str, counter: str, quote: str, **kw) -> None:
    """Добавить позитивный кейс: модель не допустила дефект категории ``counter``."""
    row = {"turn": turn, "set": set_code, "counter": counter, "quote": quote, "sec": "3",
           "behaviour": "", "uq_turn": None, "uq": ""}
    row.update(kw)
    NEGATIVES.append(row)


def sc(criterion: str, turn: int, uq: str, sec: str, counters: list[str]) -> None:
    """Добавить критерий успеха, основанный на дословной цитате БА."""
    SUCCESS_CRITERIA.append({"id": f"SC-{len(SUCCESS_CRITERIA) + 1:02d}", "turn": turn,
                             "sec": sec, "counters": counters, "uq": uq, "criterion": criterion})


